import { resourceList, resourceDel, resourceCollect, resourceLearn, collectDelete } from "@/api/ictOperation/index"
import {mapGetters,mapState} from "vuex";

export default {
  props: ['searchText'],
  data() {
    return{
      videoList: [],
      total: 0,
      searchForm: {
        current: 1,
        size: 20,
        tag: 1,
        resourceCondition: this.searchText
      },
      pageLoading: false
    }
  },
  computed: {
    ...mapGetters(["permission", "userInfo"]),
    isRoleAlias(){
      return this.$store.state.user.userDetail.roleAlias.includes('control_solver')
    }
  },
  mounted() {
    this.getList()
  },
  methods: {
    del(item){
       this.$confirm("是否确认删除!","提示",{
          confirmButtonText:"确认",
          cancelButtonText:"取消",
          type:"warning"
        }).then(()=>{
            resourceDel(item.id).then(res=>{
              this.getList()
              this.$emit('refresh', '1')
              this.$message.success('删除成功!')
            })  
        })

    },
    getList() {
      this.pageLoading = true
      resourceList(this.searchForm).then(res => {
        this.videoList = res.data.records
        this.total = res.data.total
        this.pageLoading = false
      })
    },
    search() {
      this.searchForm.current = 1
      this.searchForm.resourceCondition = this.searchText
      this.getList()
    },
    seeDetail(item, index) {
      this.$router.push({
        path: '/resourceDetail',
        query: {id: item.id, type: '视频'}
      })
    },
    downLoad(item) {
      const a = document.createElement('a')
      fetch(item.path).then(res => res.blob()).then(blob => {
        a.href = URL.createObjectURL(blob)
        a.download = item.fileName
        document.body.appendChild(a)
        a.click()
      })
    },

    collect(item){
      resourceCollect({
        type: 1,
        knowledgeId: item.id,
        userId: this.userInfo.userId 
      }).then(res=>{
        this.getList()
        this.$message.success('操作成功!')
      }) 
    },
    collect2(item){
      collectDelete({id: item.id}).then(res => {
        this.getList()
        this.$message.success('操作成功!')
      })
    },
    learn(item){
      resourceLearn({
        type: 1,
        knowledgeId: item.id,
        userId: this.userInfo.userId 
      }).then(res=>{
        this.getList()
        this.$message.success('操作成功!')
      }) 
    },
  }
}
